        shareClassCodes: prop("string", "Optional share-class codes filter (comma/pipe-separated), merged with any ShareClass limitation into ShareClassCodes."),
        labelMode: prop("string", "Classification mode for reading limitation labels. Default 'Smart Page' (use 'Library Shell' for a Smart Shell id)."),
        limit: prop("integer", "Maximum rows to return when browsing. Default 200."),
